SEG = 'HIP'
CAT = 'cpbHipaa'
Q = [
("Under HIPAA's right of access, how long does a practice have to act on a patient's request for records?",
 '30 days, with one 30-day extension', ['10 days, with no extension', '60 days, with one 30-day extension', '30 days, with unlimited extensions'],
 '45 CFR 164.524 requires action within 30 days and allows one extension of up to 30 more days with written notice of the reason.'),
("Which cost may be included in the fee for a patient's copy of her records?",
 'Labor for making the copy', ['Time spent searching for the file', 'A records retrieval fee', 'Overhead for the records room'],
 'The reasonable, cost-based fee may cover copying labor, supplies, postage and an agreed summary, not search and retrieval.'),
('How long must HIPAA security policies and required documentation be kept?',
 '6 years from creation or last use', ['3 years from creation', '10 years from the last patient visit', '6 years from the last claim paid'],
 '45 CFR 164.316(b)(2) requires 6 years from the date of creation or the date last in effect, whichever is later.'),
('How long should a signed ABN be kept when no stricter state rule applies?',
 '5 years from the date of care', ['1 year from the date of care', '7 years from the claim date', 'Until the claim is fully paid'],
 'CMS asks notifiers to keep ABNs for 5 years from the date of care delivery when no other state requirement applies.'),
('A practice routinely waives Medicare copays for all patients, regardless of need. Which concern does the OIG raise?',
 'Inducement to beneficiaries', ['Unbundling of the services', 'A Stark designated health service', 'A HIPAA privacy breach'],
 'The OIG warns that routine copay waivers can be inducements under section 1128A(a)(5) and may implicate the False Claims Act.'),
('A physician waives the whole fee for her staff, chosen without regard to referrals. How does the OIG view it?',
 'Likely not a problem', ['Always an Anti-Kickback violation', 'A Stark Law violation', 'Always a False Claims Act case'],
 "OIG guidance says regular professional courtesy waiving the entire fee may not implicate its authorities if recipients aren't chosen for referrals."),
("Which is one of the OIG's seven basic components of a practice compliance program?",
 'Periodic internal audits', ['Annual fee schedule review', 'Quarterly payer contract renewals', 'Monthly patient surveys'],
 'The seven components include internal monitoring and auditing, written standards, a compliance contact, training, response, communication and discipline.'),
('A practice finds a billing error during an internal audit. Which compliance step does the OIG expect?',
 'Investigate and correct it', ['Fix only future claims', 'Note it for the annual audit', 'Refile them as new claims'],
 "Responding to detected problems, including investigation and disclosure where needed, is one of the OIG's seven components."),
('Who must the practice check against the OIG exclusion list?',
 'Staff and contractors', ['Only licensed clinicians', 'Only physicians who bill', 'Only vendors over a set amount'],
 'Excluded individuals cannot bill federal programs directly or indirectly, so practices screen staff and contractors.'),
('Which law forbids a physician referring Medicare patients for designated health services to an entity a family member owns?',
 'Stark Law', ['Anti-Kickback Statute', 'False Claims Act', 'Civil Monetary Penalties Law'],
 'The physician self-referral (Stark) law covers financial relationships of the physician or an immediate family member.'),
('A lab gives a practice free staff in return for its test referrals. Which law is most directly involved?',
 'Anti-Kickback Statute', ['Stark Law', 'HIPAA Privacy Rule', 'Fair Debt Collection Practices Act'],
 'The AKS bars knowingly giving or receiving anything of value to induce referrals of federal program business.'),
('An Anti-Kickback safe harbor protects an arrangement only if it:',
 'Meets every requirement', ['Meets most of the requirements', 'Is approved by the local MAC', 'Involves no cash payment'],
 'OIG guidance says safe harbors protect arrangements only when they fit every requirement of the safe harbor.'),
]
